const fmt=d3.format(','),pct=d3.format('.1%'),f2=d3.format('.2f');
const POSO=[['F','Forwards (C, L, R)'],['D','Defensemen'],['G','Goalies']];
const POSL={F:'forwards',D:'defensemen',G:'goalies'};
const DECO=[['1960s','1960s (1960-61 to 1969-70)'],['1970s','1970s (1970-71 to 1979-80)'],['1980s','1980s (1980-81 to 1989-90)'],['1990s','1990s (1990-91 to 1999-00)'],['2000s','2000s (2000-01 to 2009-10)'],['2010s','2010s (2010-11 to 2019-20)'],['2020s','2020s (2020-21 to 2026-27 to date)']];
const DECS=['1960s','1970s','1980s','1990s','2000s','2010s','2020s'];
const LAB={points:'Points',goals:'Goals',assists:'Assists',gp:'Games played',ppg:'Points per game',players:'Players'};
const ppg=(p,g)=>g?p/g:0;
const S=(v)=>v?String(v).split('|'):[];
const has=(a,x)=>!a.length||a.includes(x);
function scope(p){const D=S(p.decade),P=S(p.position),C=S(p.conference);return (D.length?D.join(' + '):'all seven decades')+' · '+(P.length?P.map(k=>POSL[k]).join(' + '):'all positions')+' · '+(C.length?C.join(' + '):'all conferences');}
function sorted(rows,k,dir){const s=dir==='asc'?1:-1;return rows.slice().sort((a,b)=>{const x=a[k],y=b[k];const c=(typeof x==='string')?x.localeCompare(y):(x-y);if(c)return c*s;const d=b.points-a.points;return d||String(a.name||a.player).localeCompare(String(b.name||b.player));});}
function group(rows,by){const m=new Map();for(const r of rows){const k=by==='conference'?r.conference:r.school;let o=m.get(k);if(!o){o={name:k,conference:r.conference,seen:new Set(),sch:new Set(),gp:0,goals:0,assists:0,points:0};m.set(k,o);}o.seen.add(r.player+'|'+r.school);o.sch.add(r.school);o.gp+=r.gp;o.goals+=r.goals;o.assists+=r.assists;o.points+=r.points;}return [...m.values()].map(o=>({name:o.name,conference:o.conference,schools:o.sch.size,players:o.seen.size,gp:o.gp,goals:o.goals,assists:o.assists,points:o.points,ppg:ppg(o.points,o.gp)}));}
function denom(L,D,P){const o={gp:0,goals:0,assists:0,points:0};for(const l of L){if(!has(D,l.decade)||!has(P,l.group))continue;o.gp+=+l.gp;o.goals+=+l.goals;o.assists+=+l.assists;o.points+=+l.points;}return o;}
function shares(o,d){return {sgp:d.gp?o.gp/d.gp:0,sgoals:d.goals?o.goals/d.goals:0,sassists:d.assists?o.assists/d.assists:0,spoints:d.points?o.points/d.points:0};}
dash.calc('base',{title:'Alumni rows in this view',description:'Player-decade rows after the decade, position and conference filters, with each school current conference attached.',inputs:['players','schools'],fn:(pl,sc)=>{const p=dash.params();const D=S(p.decade),P=S(p.position),C=S(p.conference);const cf={};for(const s of sc)cf[s.school]=s.conference;return pl.filter(r=>has(D,r.decade)&&has(P,r.group)&&has(C,cf[r.school])).map(r=>({player:r.player,school:r.school,pos:r.pos,group:r.group,decade:r.decade,conference:cf[r.school]||'Other / unverified',gp:+r.gp,goals:+r.goals,assists:+r.assists,points:+r.points}));}});
dash.calc('agg',{title:'Production by school or conference',description:'Alumni totals grouped by school or conference, sorted by the chosen column.',inputs:['base'],fn:(b)=>{const p=dash.params();return sorted(group(b,p.by||'school'),p.sort||'points',p.dir||'desc');}});
dash.calc('totals',{title:'Totals for this view',description:'Sum over every alumnus in view.',inputs:['base','agg'],fn:(b,a)=>{const seen=new Set();let gp=0,goals=0,assists=0,points=0;for(const r of b){seen.add(r.player+'|'+r.school);gp+=r.gp;goals+=r.goals;assists+=r.assists;points+=r.points;}return [{n:a.length,players:seen.size,gp,goals,assists,points,ppg:ppg(points,gp)}];}});
dash.calc('plist',{title:'Players at the selected schools',description:'Per-player totals for the selected schools.',inputs:['base'],fn:(b)=>{const p=dash.params();const Sc=S(p.school);if(!Sc.length)return [];const m=new Map();for(const r of b){if(!Sc.includes(r.school))continue;const k=r.player+'|'+r.school;let o=m.get(k);if(!o){o={player:r.player,school:r.school,pos:r.pos,gp:0,goals:0,assists:0,points:0};m.set(k,o);}o.gp+=r.gp;o.goals+=r.goals;o.assists+=r.assists;o.points+=r.points;}const a=[...m.values()].map(o=>({...o,ppg:ppg(o.points,o.gp)}));return sorted(a,p.psort||'points',p.pdir||'desc');}});
dash.calc('impact',{title:'Share of the NHL by school or conference',description:'Alumni totals divided by all-NHL totals for the same decades and positions.',inputs:['base','league'],fn:(b,L)=>{const p=dash.params();const d=denom(L,S(p.decade),S(p.position));const rows=group(b,p.iby||'school').map(r=>({...r,...shares(r,d)}));return sorted(rows,p.isort||'spoints',p.idir||'desc');}});
dash.calc('itot',{title:'Share of the NHL for everything in view',description:'All alumni in view divided by all-NHL totals.',inputs:['base','league'],fn:(b,L)=>{const p=dash.params();const d=denom(L,S(p.decade),S(p.position));const seen=new Set();const o={gp:0,goals:0,assists:0,points:0};for(const r of b){seen.add(r.player+'|'+r.school);o.gp+=r.gp;o.goals+=r.goals;o.assists+=r.assists;o.points+=r.points;}return [{...o,players:seen.size,...shares(o,d)}];}});
dash.calc('trend',{title:'College share by decade',description:'Alumni share of all-NHL games, goals, assists and points in each decade, for the chosen positions and conferences.',inputs:['players','schools','league'],fn:(pl,sc,L)=>{const p=dash.params();const P=S(p.position),C=S(p.conference);const cf={};for(const s of sc)cf[s.school]=s.conference;return DECS.map(dec=>{const o={gp:0,goals:0,assists:0,points:0};for(const r of pl){if(r.decade!==dec)continue;if(!has(P,r.group))continue;if(!has(C,cf[r.school]))continue;o.gp+=+r.gp;o.goals+=+r.goals;o.assists+=+r.assists;o.points+=+r.points;}return {decade:dec,...o,...shares(o,denom(L,[dec],P))};});}});
document.querySelectorAll('#f-reset').forEach(b=>b.addEventListener('click',()=>dash.resetParams()));
function mk(name,param,dflt,opts){dash.draw(name,(el)=>{const v=dash.params()[param]||dflt;el.replaceChildren(...opts().map(o=>new Option(o[1],o[0])));el.value=v;el.onchange=()=>dash.setParams({[param]:el.value});});}
function mkm(name,param,allLabel,opts){dash.draw(name,(el)=>{const cur=S(dash.params()[param]);const old=el.querySelector('details');const wasOpen=old?old.open:false;const o=opts();const det=document.createElement('details');det.open=false;const sm=document.createElement('summary');const lab=o.filter(x=>cur.includes(x[0])).map(x=>x[1]);sm.textContent=!cur.length?allLabel:(cur.length===1&&lab.length===1?lab[0]:cur.length+' selected');det.appendChild(sm);const pn=document.createElement('div');pn.className='pn';const clr=document.createElement('button');clr.type='button';clr.className='cha-btn';clr.textContent='Clear (show all)';clr.onclick=()=>dash.setParams({[param]:''});pn.appendChild(clr);o.forEach(x=>{const l=document.createElement('label');const c=document.createElement('input');c.type='checkbox';c.value=x[0];c.checked=cur.includes(x[0]);c.onchange=()=>{const v=[...pn.querySelectorAll('input:checked')].map(i=>i.value);dash.setParams({[param]:v.join('|')});};l.append(c,document.createTextNode(x[1]));pn.appendChild(l);});det.appendChild(pn);el.replaceChildren(det);});}
mkm('s_decade','decade','All seven decades',()=>DECO);
mkm('s_pos','position','All positions',()=>POSO);
mkm('s_conf','conference','All conferences',()=>{const g=dash.data('schools');const c=g.status==='ok'?[...new Set(g.data.map(r=>r.conference))].sort():[];return c.map(x=>[x,x]);});
mkm('s_school','school','Choose schools',()=>{const g=dash.data('schools');const c=S(dash.params().conference);const s=g.status==='ok'?g.data.filter(r=>has(c,r.conference)).map(r=>r.school).sort():[];return s.map(x=>[x,x]);});
mk('s_by','by','school',()=>[['school','School'],['conference','Conference']]);
mk('s_iby','iby','school',()=>[['school','School'],['conference','Conference']]);
mk('s_metric','metric','points',()=>Object.entries(LAB));
mk('s_imetric','imetric','points',()=>[['points','Share of points'],['goals','Share of goals'],['assists','Share of assists'],['gp','Share of games played']]);
dash.draw('tabs',(el)=>{const t=dash.params().tab||'readme';el.replaceChildren(...[['readme','Read me'],['alumni','Alumni production'],['impact','Share by decade'],['seasons','Share by season'],['players','Players'],['dev','Development & honors'],['now','Active now'],['prog','Program context'],['h2h','Head to head']].map(k=>{const b=document.createElement('button');b.type='button';b.className='cha-tab'+(t===k[0]?' on':'');b.textContent=k[1];b.setAttribute('role','tab');b.setAttribute('aria-selected',String(t===k[0]));b.onclick=()=>dash.setParams({tab:k[0]});return b;}));});
dash.draw('panCss',(el)=>{const t=dash.params().tab||'readme';const s=document.createElement('style');s.textContent=[['readme','#panR'],['alumni','#panA'],['impact','#panB'],['seasons','#panC'],['players','#panD'],['dev','#panE'],['now','#panF'],['prog','#panG'],['h2h','#panH']].filter(k=>k[0]!==t).map(k=>k[1]).join(',')+'{display:none !important}'+(['now','prog'].includes(t)?'#fDec{display:none !important}':'')+(t==='readme'?'#fBar{display:none !important}':'');el.replaceChildren(s);});
const KA={kA_n:['n',fmt],kA_players:['players',fmt],kA_gp:['gp',fmt],kA_goals:['goals',fmt],kA_assists:['assists',fmt],kA_points:['points',fmt],kA_ppg:['ppg',f2]};
for(const [n,fv] of Object.entries(KA)){dash.draw(n,(el)=>{const g=dash.data('totals');el.textContent=(g.status==='ok'&&g.data&&g.data[0])?fv[1](g.data[0][fv[0]]):'—';});}
dash.draw('kA_ncap',(el)=>{el.textContent=(dash.params().by==='conference')?'Conferences':'Schools';});
const KB={kB_sgp:['sgp',pct],kB_sgoals:['sgoals',pct],kB_sassists:['sassists',pct],kB_spoints:['spoints',pct],kB_players:['players',fmt]};
for(const [n,fv] of Object.entries(KB)){dash.draw(n,(el)=>{const g=dash.data('itot');el.textContent=(g.status==='ok'&&g.data&&g.data[0])?fv[1](g.data[0][fv[0]]):'—';});}
function chartRows(rows,m,by){let r=rows.slice();if(m==='ppg')r=r.filter(x=>x.gp>=(by==='conference'?1000:200));return sorted(r,m,'desc').slice(0,15);}
dash.draw('leadA',(el)=>{const g=dash.data('agg');const p=dash.params();if(g.status!=='ok'||!g.data||!g.data.length){el.textContent='No alumni match these filters.';return;}const m=p.metric||'points';const n=chartRows(g.data,m,p.by).slice(0,3).map(x=>x.name);if(!n.length){el.textContent='—';return;}el.textContent=n[0]+' leads '+(p.by==='conference'?'conferences':'schools')+' in '+LAB[m].toLowerCase()+(n[1]?', ahead of '+n[1]+(n[2]?' and '+n[2]:''):'')+' ('+scope(p)+').';});
dash.draw('leadB',(el)=>{const g=dash.data('itot');const p=dash.params();if(g.status!=='ok'||!g.data||!g.data[0]){el.textContent='—';return;}const t=g.data[0];el.textContent='Alumni of the tracked programs played '+pct(t.sgp)+' of NHL games and recorded '+pct(t.sgoals)+' of goals, '+pct(t.sassists)+' of assists and '+pct(t.spoints)+' of points ('+scope(p)+').';});
function bars(el,rows,vf,ff,cap,tf,oc){if(!rows.length){el.textContent='Nothing matches these filters.';return;}const W=Math.max(280,el.clientWidth||600),rowH=26,top=20,H=top+rows.length*rowH+4;const svg=d3.create('svg').attr('role','img').attr('aria-label',cap).attr('width',W).attr('height',H).attr('viewBox','0 0 '+W+' '+H).style('display','block').style('max-width','100%');const tip=document.createElement('div');tip.className='cha-tip';tip.style.display='none';el.replaceChildren(svg.node(),tip);svg.append('text').attr('x',2).attr('y',12).style('font-size','11px').style('fill','var(--cds-text-secondary)').text(cap);let left=0;const probe=svg.append('text').style('font-size','12px');rows.forEach(r=>{probe.text(r.name);left=Math.max(left,probe.node().getComputedTextLength());});probe.remove();left=Math.ceil(left)+12;const right=70;const x=d3.scaleLinear().domain([0,d3.max(rows,vf)||1]).range([left,W-right]);const row=svg.selectAll('g.r').data(rows).join('g').attr('class','r').attr('transform',(d,i)=>'translate(0,'+(top+i*rowH)+')');row.append('text').attr('x',left-8).attr('y',rowH/2).attr('dy','0.32em').attr('text-anchor','end').style('font-size','12px').style('fill','var(--cds-text-secondary)').text(d=>d.name);row.append('rect').attr('x',left).attr('y',3).attr('height',rowH-8).attr('rx',3).attr('width',d=>Math.max(1,x(vf(d))-left)).style('fill',dash.colors[0]);row.append('text').attr('x',d=>x(vf(d))+6).attr('y',rowH/2).attr('dy','0.32em').style('font-size','12px').style('fill','var(--cds-text-secondary)').style('font-variant-numeric','tabular-nums').text(d=>ff(vf(d)));row.on('mousemove',(ev,d)=>{const b=el.getBoundingClientRect();tip.style.display='block';tip.textContent=tf(d);const tx=Math.min(ev.clientX-b.left+12,Math.max(0,b.width-tip.offsetWidth));tip.style.left=tx+'px';tip.style.top=Math.max(0,ev.clientY-b.top-34)+'px';}).on('mouseleave',()=>{tip.style.display='none';});if(oc)row.style('cursor','pointer').on('click',(ev,d)=>oc(d));}
dash.draw('chAh',(el)=>{const p=dash.params();el.textContent=(p.by==='conference'?'Conferences ranked — ':'Top 15 schools — ')+LAB[p.metric||'points'];});
dash.draw('chA',(el)=>{const g=dash.data('agg');if(g.status!=='ok'||!g.data){el.textContent='—';return;}const p=dash.params();const m=p.metric||'points';const rows=chartRows(g.data,m,p.by);const note=(m==='ppg')?' (min '+(p.by==='conference'?'1,000':'200')+' GP)':'';const vf=d=>d[m];const ff=m==='ppg'?f2:fmt;bars(el,rows,vf,ff,'Measure: '+LAB[m]+note+' · '+scope(p),d=>d.name+(p.by==='conference'?'':' ('+d.conference+')')+': '+fmt(d.points)+' PTS, '+fmt(d.goals)+' G, '+fmt(d.assists)+' A, '+fmt(d.gp)+' GP, '+f2(d.ppg)+' PPG, '+fmt(d.players)+' players');});
dash.draw('chBh',(el)=>{const p=dash.params();const m=p.imetric||'points';el.textContent=(p.iby==='conference'?'Conferences ranked — share of NHL ':'Top 15 schools — share of NHL ')+LAB[m].toLowerCase();});
dash.draw('chB',(el)=>{const g=dash.data('impact');if(g.status!=='ok'||!g.data){el.textContent='—';return;}const p=dash.params();const m=p.imetric||'points';const k='s'+m;const rows=sorted(g.data,k,'desc').slice(0,15);bars(el,rows,d=>d[k],pct,'Measure: share of NHL '+LAB[m].toLowerCase()+' · '+scope(p),d=>d.name+(p.iby==='conference'?'':' ('+d.conference+')')+': '+pct(d.sgp)+' of games, '+pct(d.sgoals)+' of goals, '+pct(d.sassists)+' of assists, '+pct(d.spoints)+' of points');});
function tbl(el,res,cols,sort,dir,sk,dk,onrow){if(res.status!=='ok'||!res.data){el.replaceChildren();return;}const t=document.createElement('table');const hr=t.createTHead().insertRow();const h0=document.createElement('th');h0.textContent='#';hr.appendChild(h0);cols.forEach(c=>{const th=document.createElement('th');th.textContent=c.l+(sort===c.f?(dir==='asc'?' ▲':' ▼'):'');if(c.t==='text')th.className='l';th.tabIndex=0;th.setAttribute('aria-sort',sort===c.f?(dir==='asc'?'ascending':'descending'):'none');const go=()=>{const nd=sort===c.f?(dir==='desc'?'asc':'desc'):(c.t==='text'?'asc':'desc');dash.setParams({[sk]:c.f,[dk]:nd});};th.onclick=go;th.onkeydown=(e)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go();}};hr.appendChild(th);});const tb=t.createTBody();res.data.forEach((r,i)=>{const tr=tb.insertRow();if(onrow){tr.className='pick';tr.onclick=()=>onrow(r);}let td=tr.insertCell();td.textContent=i+1;cols.forEach(c=>{td=tr.insertCell();if(c.t==='text')td.className='l';td.textContent=c.fm?c.fm(r[c.f]):r[c.f];});});el.replaceChildren(t);}
function aCols(by){const n=[{f:'name',l:by==='conference'?'Conference':'School',t:'text'}];n.push(by==='conference'?{f:'schools',l:'Schools'}:{f:'conference',l:'Conference',t:'text'});return n;}
dash.draw('tbAh',(el)=>{el.textContent=dash.params().by==='conference'?'All conferences':'All schools';});
dash.draw('tbA',(el)=>{const p=dash.params();const by=p.by||'school';const cols=[...aCols(by),{f:'players',l:'Players',fm:fmt},{f:'gp',l:'GP',fm:fmt},{f:'goals',l:'G',fm:fmt},{f:'assists',l:'A',fm:fmt},{f:'points',l:'PTS',fm:fmt},{f:'ppg',l:'PPG',fm:f2}];tbl(el,dash.data('agg'),cols,p.sort||'points',p.dir||'desc','sort','dir',by==='school'?(r)=>{const cur=S(dash.params().school);dash.setParams({school:(cur.includes(r.name)?cur.filter(x=>x!==r.name):[...cur,r.name]).join('|')});}:null);});
dash.draw('tbBh',(el)=>{el.textContent=dash.params().iby==='conference'?'All conferences':'All schools';});
dash.draw('tbB',(el)=>{const p=dash.params();const by=p.iby||'school';const cols=[...aCols(by),{f:'players',l:'Players',fm:fmt},{f:'gp',l:'GP',fm:fmt},{f:'sgp',l:'% of NHL GP',fm:pct},{f:'goals',l:'G',fm:fmt},{f:'sgoals',l:'% of NHL G',fm:pct},{f:'assists',l:'A',fm:fmt},{f:'sassists',l:'% of NHL A',fm:pct},{f:'points',l:'PTS',fm:fmt},{f:'spoints',l:'% of NHL PTS',fm:pct}];tbl(el,dash.data('impact'),cols,p.isort||'spoints',p.idir||'desc','isort','idir',null);});
dash.draw('plh',(el)=>{const p=dash.params();const Sc=S(p.school);const g=dash.data('plist');el.textContent=Sc.length?('Players from '+Sc.join(', ')+(g.status==='ok'&&g.data?' — '+g.data.length:'')):'Players by school';});
dash.draw('plT',(el)=>{const p=dash.params();const g=dash.data('plist');if(!S(p.school).length){el.textContent='Choose one or more schools in the School players menu, or click school rows above, to list their alumni.';return;}const cols=[{f:'player',l:'Player',t:'text'},{f:'school',l:'School',t:'text'},{f:'pos',l:'Pos',t:'text'},{f:'gp',l:'GP',fm:fmt},{f:'goals',l:'G',fm:fmt},{f:'assists',l:'A',fm:fmt},{f:'points',l:'PTS',fm:fmt},{f:'ppg',l:'PPG',fm:f2}];tbl(el,g,cols,p.psort||'points',p.pdir||'desc','psort','pdir',null);});
dash.draw('trh',(el)=>{const p=dash.params();const P=S(p.position),C=S(p.conference);el.textContent='College share of the NHL by decade — '+(P.length?P.map(k=>POSL[k]).join(' + '):'all positions')+', '+(C.length?C.join(' + '):'all conferences');});
dash.draw('trend',(el)=>{const g=dash.data('trend');if(g.status!=='ok'||!g.data){el.textContent='—';return;}const rows=g.data;const keys=[['sgp','Games'],['sgoals','Goals'],['sassists','Assists'],['spoints','Points']];const W=Math.max(300,el.clientWidth||600),H=250,m={t:30,r:8,b:26,l:44};const svg=d3.create('svg').attr('role','img').attr('aria-label','Grouped bars of the college share of NHL games, goals, assists and points in each decade').attr('width',W).attr('height',H).attr('viewBox','0 0 '+W+' '+H).style('display','block').style('max-width','100%');const x0=d3.scaleBand().domain(keys.map(k=>k[0])).range([m.l,W-m.r]).paddingInner(0.2);const x1=d3.scaleBand().domain(DECS).range([0,x0.bandwidth()]).padding(0.08);const ymax=d3.max(rows,r=>d3.max(keys,k=>r[k[0]]))||0.1;const y=d3.scaleLinear().domain([0,ymax*1.15]).range([H-m.b,m.t]);y.ticks(4).forEach(t=>{svg.append('line').attr('x1',m.l).attr('x2',W-m.r).attr('y1',y(t)).attr('y2',y(t)).style('stroke','var(--color-border-line)');svg.append('text').attr('x',m.l-6).attr('y',y(t)).attr('dy','0.32em').attr('text-anchor','end').style('font-size','10px').style('fill','var(--cds-text-secondary)').text(d3.format('.0%')(t));});const small=x1.bandwidth()<34;keys.forEach(k=>{const gx=x0(k[0]);svg.append('text').attr('x',gx+x0.bandwidth()/2).attr('y',H-8).attr('text-anchor','middle').style('font-size','12px').style('fill','var(--cds-text-secondary)').text('Share of '+k[1].toLowerCase());rows.forEach(r=>{const bx=gx+x1(r.decade);const v=r[k[0]];svg.append('rect').attr('x',bx).attr('y',y(v)).attr('width',x1.bandwidth()).attr('height',Math.max(0,y(0)-y(v))).attr('rx',2).style('fill',dash.colors[DECS.indexOf(r.decade)%dash.colors.length]).append('title').text(r.decade+': '+pct(v)+' of NHL '+k[1].toLowerCase());svg.append('text').attr('x',bx+x1.bandwidth()/2).attr('y',y(v)-4).attr('text-anchor','middle').style('font-size',small?'9px':'10px').style('fill','var(--cds-text-secondary)').text(d3.format(small?'.0%':'.1%')(v));});});DECS.forEach((d,i)=>{const lx=m.l+i*54;svg.append('rect').attr('x',lx).attr('y',6).attr('width',10).attr('height',10).attr('rx',2).style('fill',dash.colors[i%dash.colors.length]);svg.append('text').attr('x',lx+15).attr('y',15).style('font-size','11px').style('fill','var(--cds-text-secondary)').text(d);});el.replaceChildren(svg.node());});
function sdenom(L,D,P,Sel){const o={gp:0,goals:0,assists:0,points:0};for(const l of L){if(!has(D,l.decade)||!has(P,l.group)||!has(Sel,l.season))continue;o.gp+=+l.gp;o.goals+=+l.goals;o.assists+=+l.assists;o.points+=+l.points;}return o;}
function sgroup(rows,by){const m=new Map();for(const r of rows){const k=by==='conference'?r.conference:r.school;let o=m.get(k);if(!o){o={name:k,conference:r.conference,sch:new Set(),players:0,gp:0,goals:0,assists:0,points:0};m.set(k,o);}o.sch.add(r.school);o.players+=r.n;o.gp+=r.gp;o.goals+=r.goals;o.assists+=r.assists;o.points+=r.points;}return [...m.values()].map(o=>({name:o.name,conference:o.conference,schools:o.sch.size,players:o.players,gp:o.gp,goals:o.goals,assists:o.assists,points:o.points,ppg:ppg(o.points,o.gp)}));}
dash.calc('sbase',{title:'Alumni rows by season',description:'Season rows of tracked alumni after the decade, position and conference filters.',inputs:['seasons','schools'],fn:(sr,sc)=>{const p=dash.params();const D=S(p.decade),P=S(p.position),C=S(p.conference);const cf={};for(const s of sc)cf[s.school]=s.conference;return sr.filter(r=>has(D,r.decade)&&has(P,r.group)&&has(C,cf[r.school])).map(r=>({season:r.season,school:r.school,conference:cf[r.school]||'Other / unverified',group:r.group,gp:+r.gp,goals:+r.goals,assists:+r.assists,points:+r.points,n:+r.players}));}});
dash.calc('sbyseason',{title:'College share of the NHL, season by season',description:'For each NHL season in the chosen decades: alumni totals and their share of all-NHL totals, for the chosen positions and conferences.',inputs:['sbase','league_seasons'],fn:(b,L)=>{const p=dash.params();const D=S(p.decade),P=S(p.position);const m=new Map();for(const l of L){if(!has(D,l.decade)||!has(P,l.group))continue;let o=m.get(l.season);if(!o){o={season:l.season,gp:0,goals:0,assists:0,points:0,players:0,d:{gp:0,goals:0,assists:0,points:0}};m.set(l.season,o);}o.d.gp+=+l.gp;o.d.goals+=+l.goals;o.d.assists+=+l.assists;o.d.points+=+l.points;}for(const r of b){const o=m.get(r.season);if(!o)continue;o.gp+=r.gp;o.goals+=r.goals;o.assists+=r.assists;o.points+=r.points;o.players+=r.n;}return [...m.values()].sort((a,c)=>a.season.localeCompare(c.season)).map(o=>({season:o.season,players:o.players,gp:o.gp,goals:o.goals,assists:o.assists,points:o.points,...shares(o,o.d)}));}});
dash.calc('srank',{title:'Share of the NHL by school or conference, chosen seasons',description:'Alumni totals in the chosen seasons divided by all-NHL totals for the same seasons and positions.',inputs:['sbase','league_seasons'],fn:(b,L)=>{const p=dash.params();const Sel=S(p.season);const d=sdenom(L,S(p.decade),S(p.position),Sel);const rows=sgroup(b.filter(r=>has(Sel,r.season)),p.sby||'school').map(r=>({...r,...shares(r,d)}));return sorted(rows,p.ssort||'spoints',p.sdir||'desc');}});
dash.calc('stot',{title:'Share of the NHL for everything in view, chosen seasons',description:'All alumni season rows in view divided by all-NHL totals for the same seasons.',inputs:['sbase','league_seasons'],fn:(b,L)=>{const p=dash.params();const Sel=S(p.season);const d=sdenom(L,S(p.decade),S(p.position),Sel);const o={gp:0,goals:0,assists:0,points:0,players:0};for(const r of b){if(!has(Sel,r.season))continue;o.gp+=r.gp;o.goals+=r.goals;o.assists+=r.assists;o.points+=r.points;o.players+=r.n;}return [{...o,...shares(o,d)}];}});
