dash.draw('strend',(el)=>{const g=dash.data('sbyseason');if(g.status!=='ok'||!g.data){el.textContent='—';return;}const rows=g.data;if(!rows.length){el.textContent='Nothing matches these filters.';return;}const keys=[['sgp','Games'],['sgoals','Goals'],['sassists','Assists'],['spoints','Points']];const W=Math.max(300,el.clientWidth||600),H=290,m={t:34,r:12,b:34,l:44};const sel=S(dash.params().season);const svg=d3.create('svg').attr('role','img').attr('aria-label','Lines of the college share of NHL games, goals, assists and points in each season').attr('width',W).attr('height',H).attr('viewBox','0 0 '+W+' '+H).style('display','block').style('max-width','100%');const x=d3.scalePoint().domain(rows.map(r=>r.season)).range([m.l+8,W-m.r-8]);const y=d3.scaleLinear().domain([0,(d3.max(rows,r=>d3.max(keys,k=>r[k[0]]))||0.1)*1.1]).range([H-m.b,m.t]);y.ticks(5).forEach(t=>{svg.append('line').attr('x1',m.l).attr('x2',W-m.r).attr('y1',y(t)).attr('y2',y(t)).style('stroke','var(--color-border-line)');svg.append('text').attr('x',m.l-6).attr('y',y(t)).attr('dy','0.32em').attr('text-anchor','end').style('font-size','10px').style('fill','var(--cds-text-secondary)').text(d3.format('.0%')(t));});const bw=rows.length>1?x(rows[1].season)-x(rows[0].season):40;rows.forEach(r=>{if(sel.includes(r.season))svg.append('rect').attr('x',x(r.season)-bw/2).attr('y',m.t).attr('width',bw).attr('height',H-m.b-m.t).style('fill','var(--color-fg)').style('opacity',0.1);});const step=Math.max(1,Math.ceil(rows.length/10));rows.forEach((r,i)=>{if(i%step===0)svg.append('text').attr('x',x(r.season)).attr('y',H-14).attr('text-anchor','middle').style('font-size','10px').style('fill','var(--cds-text-secondary)').text(r.season);});keys.forEach((k,ki)=>{const ln=d3.line().x(r=>x(r.season)).y(r=>y(r[k[0]]));svg.append('path').attr('d',ln(rows)).style('fill','none').style('stroke',dash.colors[ki%dash.colors.length]).style('stroke-width',2);if(rows.length<=14)rows.forEach(r=>svg.append('circle').attr('cx',x(r.season)).attr('cy',y(r[k[0]])).attr('r',3).style('fill',dash.colors[ki%dash.colors.length]));svg.append('rect').attr('x',m.l+ki*78).attr('y',8).attr('width',10).attr('height',10).attr('rx',2).style('fill',dash.colors[ki%dash.colors.length]);svg.append('text').attr('x',m.l+ki*78+15).attr('y',17).style('font-size','11px').style('fill','var(--cds-text-secondary)').text(k[1]);});rows.forEach(r=>{svg.append('rect').attr('x',x(r.season)-bw/2).attr('y',m.t).attr('width',bw).attr('height',H-m.b-m.t).style('fill','transparent').style('cursor','pointer').on('click',()=>{const cur=S(dash.params().season);dash.setParams({season:(cur.includes(r.season)?cur.filter(z=>z!==r.season):[...cur,r.season]).join('|')});}).append('title').text(r.season+': '+pct(r.sgp)+' of games, '+pct(r.sgoals)+' of goals, '+pct(r.sassists)+' of assists, '+pct(r.spoints)+' of points');});el.replaceChildren(svg.node());});
dash.draw('stbl',(el)=>{const g=dash.data('sbyseason');if(g.status!=='ok'||!g.data){el.replaceChildren();return;}const sel=S(dash.params().season);const cols=[['season','Season','l'],['players','Player-seasons',fmt],['gp','GP',fmt],['sgp','% of NHL GP',pct],['goals','G',fmt],['sgoals','% of NHL G',pct],['assists','A',fmt],['sassists','% of NHL A',pct],['points','PTS',fmt],['spoints','% of NHL PTS',pct]];const t=document.createElement('table');const hr=t.createTHead().insertRow();cols.forEach(c=>{const th=document.createElement('th');th.textContent=c[1];if(c[2]==='l')th.className='l';th.style.cursor='default';hr.appendChild(th);});const tb=t.createTBody();g.data.forEach(r=>{const tr=tb.insertRow();tr.className='pick';if(sel.includes(r.season)){tr.style.fontWeight='600';tr.style.background='rgba(127,127,127,.15)';}tr.onclick=()=>{const cur=S(dash.params().season);dash.setParams({season:(cur.includes(r.season)?cur.filter(z=>z!==r.season):[...cur,r.season]).join('|')});};cols.forEach(c=>{const td=tr.insertCell();if(c[2]==='l'){td.className='l';td.textContent=r[c[0]];}else td.textContent=c[2](r[c[0]]);});});el.replaceChildren(t);});
