dash.calc('pall',{title:'Players in this view',description:'One row per player and school: NHL totals across the chosen decades, filtered by position, conference, school, name and minimum games played.',inputs:['player_seasons','schools','player_profiles'],fn:(ps,sc,pr)=>{const pm=pmap(pr);const p=dash.params();const D=S(p.decade),P=S(p.position),C=S(p.conference),Se=S(p.pseason);const cf={};for(const s of sc)cf[s.school]=s.conference;const Sc=S(p.school);const q=(p.q||'').trim().toLowerCase();const mg=+(p.mingp||0);const m=new Map();for(const r of ps){if(!has(D,r.decade)||!has(P,r.group)||!has(C,cf[r.school])||!has(Se,r.season))continue;if(Sc.length&&!Sc.includes(r.school))continue;if(!passD(p,pm.get(r.player+'|'+r.school)))continue;if(q&&!r.player.toLowerCase().includes(q))continue;const k=r.player+'|'+r.school;let o=m.get(k);if(!o){o={name:r.player,player:r.player,school:r.school,conference:cf[r.school]||'Other / unverified',pos:r.pos,pf:pm.get(r.player+'|'+r.school),dec:new Set(),n:0,gp:0,goals:0,assists:0,points:0};m.set(k,o);}o.dec.add(r.decade);o.n++;o.gp+=r.gp;o.goals+=r.goals;o.assists+=r.assists;o.points+=r.points;}const a=[...m.values()].filter(o=>o.gp>=mg).map(o=>({name:o.name,player:o.player,school:o.school,conference:o.conference,pos:o.pos,decades:[...o.dec].sort().join(', '),seasons:o.n,...pfx(o.pf),gp:o.gp,goals:o.goals,assists:o.assists,points:o.points,ppg:ppg(o.points,o.gp)}));return sorted(a,p.tsort||'points',p.tdir||'desc');}});
