const f1=d3.format('.1f');
function pmap(arr){const m=new Map();for(const r of arr)m.set(r.player+'|'+r.school,r);return m;}
const shortT=(t)=>t.replace(' Memorial Trophy','').replace(' Memorial','').replace(' Trophy','');
const tl=(pf)=>pf&&pf.trophies?String(pf.trophies).split('|').filter(Boolean):[];
function honors(pf){const a=[];if(pf.hobey)a.push('Hobey '+pf.hobey);if(pf.cups)a.push(pf.cups>1?'Cup x'+pf.cups:'Cup');for(const t of tl(pf))a.push(shortT(t));return a.join(', ');}
function pfx(pf){return pf?{overall:pf.drafted?pf.overall:999,draftYear:pf.draftYear||0,ageDebut:pf.ageDebut||0,cups:pf.cups,hobey:pf.hobey||0,awards:pf.nTrophies||0,honors:honors(pf)}:{overall:999,draftYear:0,ageDebut:0,cups:0,hobey:0,awards:0,honors:''};}
function passD(p,pf){const d=p.pdraft||'',h=p.phonor||'';if(d){if(!pf)return false;if(d==='drafted'&&!pf.drafted)return false;if(d==='undrafted'&&pf.drafted)return false;if(d==='r1'&&pf.round!==1)return false;}if(h){if(!pf)return false;if(h==='cup'&&!(pf.cups>0))return false;if(h==='hobey'&&!pf.hobey)return false;if(h==='award'&&!(pf.nTrophies>0))return false;if(h==='g500'&&!pf.gp500)return false;}return true;}
