mk('s_phonor','phonor','',()=>[['','Any'],['cup','Stanley Cup winner'],['hobey','Hobey Baker winner'],['award','Won an NHL award'],['g500','500+ NHL games']]);
const DLAB={players:'Players',pdrafted:'Share drafted',r1:'First-round picks',avgPick:'Avg draft pick, drafted players (lowest first)',avgAge:'Avg age at NHL debut (youngest first)',avgYrs:'Avg years from last college season to NHL debut (fewest first)',cups:'Stanley Cups won',cupPl:'Stanley Cup winners',awards:'NHL individual awards',g500:'500+ game players',hobey:'Hobey Baker winners (NHL players only)'};
const DLOW=new Set(['avgPick','avgAge','avgYrs']);
const DMIN=new Set(['pdrafted','avgPick','avgAge','avgYrs']);
dash.calc('dev',{title:'Development and honors by school or conference',description:'Draft, age, path to the NHL and honors for each alumnus in view, summarized by school or conference.',inputs:['base','player_profiles'],fn:(b,pr)=>{const p=dash.params();const pm=pmap(pr);const seen=new Set();const m=new Map();for(const r of b){const k=r.player+'|'+r.school;if(seen.has(k))continue;seen.add(k);const pf=pm.get(k);if(!pf)continue;const key=(p.dby==='conference')?r.conference:r.school;let o=m.get(key);if(!o){o={name:key,conference:r.conference,sch:new Set(),players:0,drafted:0,r1:0,sumPick:0,ageN:0,ageS:0,yrN:0,yrS:0,cups:0,cupPl:0,awards:0,g500:0,hobey:0};m.set(key,o);}o.sch.add(r.school);o.players++;if(pf.drafted){o.drafted++;o.sumPick+=pf.overall;if(pf.round===1)o.r1++;}if(pf.ageDebut){o.ageN++;o.ageS+=pf.ageDebut;}if(pf.yearsCollegeToNHL!=null){o.yrN++;o.yrS+=pf.yearsCollegeToNHL;}o.cups+=pf.cups;if(pf.cups>0)o.cupPl++;o.awards+=pf.nTrophies||0;if(pf.gp500)o.g500++;if(pf.hobey)o.hobey++;}const rows=[...m.values()].map(o=>({name:o.name,conference:o.conference,schools:o.sch.size,players:o.players,drafted:o.drafted,pdrafted:o.players?o.drafted/o.players:0,r1:o.r1,avgPick:o.drafted?o.sumPick/o.drafted:0,avgAge:o.ageN?o.ageS/o.ageN:0,avgYrs:o.yrN?o.yrS/o.yrN:0,cups:o.cups,cupPl:o.cupPl,awards:o.awards,g500:o.g500,hobey:o.hobey,ageS:o.ageS,ageN:o.ageN,yrS:o.yrS,yrN:o.yrN,sumPick:o.sumPick}));return sorted(rows,p.dsort||'players',p.ddir||'desc');}});
dash.calc('devtot',{title:'Development and honors, everything in view',description:'Totals and averages across all alumni in view.',inputs:['dev'],fn:(d)=>{const o={players:0,drafted:0,r1:0,ageS:0,ageN:0,yrS:0,yrN:0,cupPl:0,g500:0,hobey:0,cups:0,awards:0};for(const r of d){for(const k of Object.keys(o))o[k]+=r[k];}return [{...o,pdrafted:o.players?o.drafted/o.players:0,avgAge:o.ageN?o.ageS/o.ageN:0,avgYrs:o.yrN?o.yrS/o.yrN:0}];}});
