function curRows(c,sc){const p=dash.params();const P=S(p.position),C=S(p.conference);const cf={};for(const s of sc)cf[s.school]=s.conference;return c.map(r=>({...r,conference:cf[r.school]||'Other / unverified'})).filter(r=>has(P,r.group)&&has(C,r.conference));}
dash.calc('cur',{title:'Alumni on 2026-27 rosters, grouped',description:'Alumni with 2026-27 NHL stats, grouped by school, conference or NHL team.',inputs:['current','schools'],fn:(c,sc)=>{const p=dash.params();const by=p.nby||'school';const m=new Map();for(const r of curRows(c,sc)){const key=by==='conference'?r.conference:by==='team'?r.team:r.school;let o=m.get(key);if(!o){o={name:key,conference:r.conference,sch:new Set(),players:0,gp:0,goals:0,assists:0,points:0,r1:0,rookies:0};m.set(key,o);}o.sch.add(r.school);o.players++;o.gp+=r.gp;o.goals+=r.goals;o.assists+=r.assists;o.points+=r.points;if(r.round===1)o.r1++;if(r.rookie)o.rookies++;}return sorted([...m.values()].map(o=>({name:o.name,conference:o.conference,schools:o.sch.size,players:o.players,gp:o.gp,goals:o.goals,assists:o.assists,points:o.points,ppg:ppg(o.points,o.gp),r1:o.r1,rookies:o.rookies})),p.nsort||'players',p.ndir||'desc');}});
dash.calc('curp',{title:'Alumni on 2026-27 rosters, by player',description:'One row per alumnus with 2026-27 NHL stats.',inputs:['current','schools'],fn:(c,sc)=>{const p=dash.params();const a=curRows(c,sc).map(r=>({name:r.player,player:r.player,school:r.school,conference:r.conference,team:r.team,pos:r.pos,gp:r.gp,goals:r.goals,assists:r.assists,points:r.points,ppg:ppg(r.points,r.gp),pick:r.drafted?r.overall:999,cups:r.cups,first:r.rookie?'Yes':''}));return sorted(a,p.npsort||'points',p.npdir||'desc');}});
dash.calc('curtot',{title:'Alumni on 2026-27 rosters, totals',description:'Sum over every alumnus in view.',inputs:['curp','current'],fn:(a,c)=>{const o={players:a.length,gp:0,goals:0,assists:0,points:0,r1:0,rookies:0};const byId=new Map();for(const r of c)byId.set(r.player+'|'+r.school,r);for(const r of a){o.gp+=r.gp;o.goals+=r.goals;o.assists+=r.assists;o.points+=r.points;const x=byId.get(r.player+'|'+r.school);if(x&&x.round===1)o.r1++;if(r.first)o.rookies++;}return [o];}});
