dash.calc('progd',{title:'Alumni output per program-year',description:'Alumni, NHL games and points divided by the seasons each program has played at Division I since 1960-61.',inputs:['players','schools','programs'],fn:(pl,sc,pg)=>{const p=dash.params();const P=S(p.position),C=S(p.conference);const by=p.gby||'school';const from={},to={};for(const r of pg){from[r.school]=+r.dFrom;to[r.school]=r.dTo?+r.dTo:2027;}const cf={};for(const s of sc)cf[s.school]=s.conference;const m=new Map();for(const s of sc){if(from[s.school]==null||!has(C,s.conference))continue;const key=by==='conference'?s.conference:s.school;let o=m.get(key);if(!o){o={name:key,conference:s.conference,sch:new Set(),players:0,gp:0,points:0,years:0,since:from[s.school]};m.set(key,o);}o.sch.add(s.school);o.years+=to[s.school]-from[s.school];o.since=Math.min(o.since,from[s.school]);}const seen=new Set();for(const r of pl){if(!has(P,r.group))continue;if(from[r.school]==null)continue;const conf=cf[r.school]||'Other / unverified';if(!has(C,conf))continue;const key=by==='conference'?conf:r.school;const o=m.get(key);if(!o)continue;const k=r.player+'|'+r.school;o.gp+=+r.gp;o.points+=+r.points;if(!seen.has(k)){seen.add(k);o.players++;}}const rows=[...m.values()].map(o=>({name:o.name,conference:o.conference,schools:o.sch.size,since:o.since,years:o.years,players:o.players,gp:o.gp,points:o.points,perDec:o.years?o.players/o.years*10:0,gpPY:o.years?o.gp/o.years:0,ptsPY:o.years?o.points/o.years:0}));return sorted(rows,p.gsort||'perDec',p.gdir||'desc');}});
