dash.calc('h2h',{title:'Head to head',description:'Two schools compared side by side on production, share of the NHL, development, honors and program age.',inputs:['players','player_profiles','programs','league'],fn:(pl,pr,pg,L)=>{const p=dash.params();const A=p.h1||'Michigan',B=p.h2||'Boston University';const D=S(p.decade),P=S(p.position);const pm=pmap(pr);const from={},to={};for(const r of pg){from[r.school]=+r.dFrom;to[r.school]=r.dTo?+r.dTo:2027;}const d=denom(L,D,P);const sum=(sch)=>{const o={gp:0,goals:0,assists:0,points:0};const seen=new Set();for(const r of pl){if(r.school!==sch||!has(D,r.decade)||!has(P,r.group))continue;o.gp+=+r.gp;o.goals+=+r.goals;o.assists+=+r.assists;o.points+=+r.points;seen.add(r.player);}let dr=0,r1=0,aS=0,aN=0,yS=0,yN=0,cupPl=0,g5=0,hb=0,aw=0;for(const nm of seen){const pf=pm.get(nm+'|'+sch);if(!pf)continue;if(pf.drafted){dr++;if(pf.round===1)r1++;}if(pf.ageDebut){aS+=pf.ageDebut;aN++;}if(pf.yearsCollegeToNHL!=null){yS+=pf.yearsCollegeToNHL;yN++;}if(pf.cups>0)cupPl++;if(pf.gp500)g5++;if(pf.hobey)hb++;aw+=pf.nTrophies||0;}const n=seen.size;const yrs=from[sch]!=null?to[sch]-from[sch]:0;const sh=shares(o,d);return {n,...o,ppg:ppg(o.points,o.gp),sgp:sh.sgp,spoints:sh.spoints,pd:n?dr/n:0,r1,age:aN?aS/aN:0,yrs:yN?yS/yN:0,cupPl,g5,hb,aw,py:yrs,per10:yrs?n/yrs*10:0};};const a=sum(A),b=sum(B);const M=[['Alumni','n','int',1],['Games played','gp','int',1],['Goals','goals','int',1],['Assists','assists','int',1],['Points','points','int',1],['Points per game','ppg','f2',1],['Share of NHL games','sgp','pct',1],['Share of NHL points','spoints','pct',1],['Share drafted','pd','pct',1],['First-round picks','r1','int',1],['Avg age at NHL debut','age','f1',-1],['Avg years college to NHL','yrs','f1',-1],['Stanley Cup winners','cupPl','int',1],['500+ game players','g5','int',1],['Hobey Baker winners (NHL players only)','hb','int',1],['NHL individual awards','aw','int',1],['Program-years','py','int',0],['Alumni per 10 program-years','per10','f2',1]];return M.map(m=>({metric:m[0],a:a[m[1]],b:b[m[1]],kind:m[2],dir:m[3],school_a:A,school_b:B}));}});
