const HF={int:fmt,f2:f2,f1:f1,pct:pct};
function hbetter(r){if(!r.dir)return 0;const x=r.a,y=r.b;if(r.dir<0){if(!x&&!y)return 0;if(!x)return 2;if(!y)return 1;return x<y?1:x>y?2:0;}return x>y?1:x<y?2:0;}
dash.draw('leadH',(el)=>{const g=dash.data('h2h');const p=dash.params();if(g.status!=='ok'||!g.data||!g.data.length){el.textContent='—';return;}const R=g.data;const A=R[0].school_a,B=R[0].school_b;if(A===B){el.textContent='Choose two different schools.';return;}const pts=R.find(r=>r.metric==='Points'),sh=R.find(r=>r.metric==='Share of NHL points'),n=R.find(r=>r.metric==='Alumni');el.textContent=A+' has '+fmt(n.a)+' alumni and '+fmt(pts.a)+' NHL points ('+pct(sh.a)+' of the NHL); '+B+' has '+fmt(n.b)+' alumni and '+fmt(pts.b)+' points ('+pct(sh.b)+') — '+scope({decade:p.decade,position:p.position,conference:''}).split(' · ').slice(0,2).join(' · ')+'.';});
