dash.draw('tbH',(el)=>{const g=dash.data('h2h');if(g.status!=='ok'||!g.data||!g.data.length){el.replaceChildren();return;}const R=g.data,A=R[0].school_a,B=R[0].school_b;const t=document.createElement('table');const hr=t.createTHead().insertRow();[['Measure','l'],[A,''],[B,'']].forEach(c=>{const th=document.createElement('th');th.textContent=c[0];if(c[1])th.className='l';th.style.cursor='default';hr.appendChild(th);});const tb=t.createTBody();R.forEach(r=>{const tr=tb.insertRow();const c0=tr.insertCell();c0.className='l';c0.textContent=r.metric;const w=hbetter(r);const mx=Math.max(r.a,r.b)||1;const fv=HF[r.kind];[[r.a,1],[r.b,2]].forEach(x=>{const td=tr.insertCell();td.style.minWidth='140px';const v=x[0];const txt=(r.dir<0&&!v)?'—':fv(v);const s=document.createElement('div');s.textContent=txt;if(w===x[1])s.style.fontWeight='700';td.appendChild(s);if(r.dir!==0&&v>0){const bar=document.createElement('div');bar.style.cssText='height:4px;border-radius:2px;margin-top:3px;margin-left:auto;width:'+Math.max(2,Math.round(v/mx*100))+'%;background:'+dash.colors[x[1]-1];td.appendChild(bar);}});});el.replaceChildren(t);});
dash.calc('pcard',{title:'Selected player career',description:'NHL seasons and profile of the player chosen on the Players tab.',inputs:['player_seasons','player_profiles'],fn:(ps,pr)=>{const pick=dash.params().pick||'';if(!pick)return [];const pf=pmap(pr).get(pick)||{};const rows=ps.filter(r=>r.player+'|'+r.school===pick).sort((a,b)=>a.season.localeCompare(b.season));return rows.map(r=>({season:r.season,pos:r.pos,gp:+r.gp,goals:+r.goals,assists:+r.assists,points:+r.points,player:r.player,school:r.school,drafted:!!pf.drafted,draftYear:pf.draftYear||0,round:pf.round||0,overall:pf.overall||0,ageDebut:pf.ageDebut||0,yrs:(pf.yearsCollegeToNHL==null?-1:pf.yearsCollegeToNHL),cups:pf.cups||0,hobey:pf.hobey||0,trophies:tl(pf).join('|')}));}});
dash.draw('pcH',(el)=>{const p=dash.params();el.textContent=p.pick?'Player detail — '+p.pick.split('|')[0]:'Player detail';});
dash.draw('pcB',(el)=>{const g=dash.data('pcard');const p=dash.params();if(!p.pick){el.textContent='No player selected yet. Click a player’s name in the All players table below (or search by name above first) and his career will appear here.';window.__lastPick='';return;}if(g.status!=='ok'||!g.data||!g.data.length){el.textContent='No seasons found for this player.';return;}const R=g.data,f=R[0];const tot=R.reduce((o,r)=>({gp:o.gp+r.gp,g:o.g+r.goals,a:o.a+r.assists,p:o.p+r.points}),{gp:0,g:0,a:0,p:0});const box=document.createElement('div');box.style.display='flex';box.style.flexDirection='column';box.style.gap='10px';const hd=document.createElement('p');hd.className='cha-lead';const hon=[];if(f.hobey)hon.push('Hobey Baker '+f.hobey);if(f.cups)hon.push(f.cups>1?f.cups+' Stanley Cups':'Stanley Cup');for(const t of f.trophies?f.trophies.split('|'):[])hon.push(shortT(t));hd.textContent=f.player+' · '+f.school+' · '+f.pos+' — '+(f.drafted?'drafted in '+f.draftYear+', round '+f.round+', pick '+f.overall:'undrafted')+(f.ageDebut?'; reached the NHL at '+f1(f.ageDebut):'')+(f.yrs>=0?', '+f.yrs+(f.yrs===1?' year':' years')+' after his last college season':'')+'.'+(hon.length?' Honors: '+hon.join(', ')+'.':'');const bt=document.createElement('button');bt.type='button';bt.className='cha-btn';bt.textContent='Clear';bt.style.alignSelf='flex-start';bt.onclick=()=>dash.setParams({pick:''});const ch=document.createElement('div');ch.className='cha-chart';const tw=document.createElement('div');tw.className='cha-wrap';const t=document.createElement('table');const hr=t.createTHead().insertRow();['Season','GP','G','A','PTS','PPG'].forEach((h,i)=>{const th=document.createElement('th');th.textContent=h;if(i===0)th.className='l';th.style.cursor='default';hr.appendChild(th);});const tb=t.createTBody();const row=(a,bold)=>{const tr=tb.insertRow();if(bold)tr.style.fontWeight='600';a.forEach((v,i)=>{const td=tr.insertCell();if(i===0)td.className='l';td.textContent=v;});};R.forEach(r=>row([r.season,fmt(r.gp),fmt(r.goals),fmt(r.assists),fmt(r.points),f2(ppg(r.points,r.gp))],false));row(['Career (NHL, tracked seasons)',fmt(tot.gp),fmt(tot.g),fmt(tot.a),fmt(tot.p),f2(ppg(tot.p,tot.gp))],true);tw.appendChild(t);box.append(hd,bt,ch,tw);el.replaceChildren(box);if(window.__lastPick!==p.pick){window.__lastPick=p.pick;const sec=el.closest('section');if(sec)sec.scrollIntoView({behavior:'smooth',block:'start'});}const m=f.pos==='G'?'gp':'points';bars(ch,R.map(r=>({name:r.season,v:r[m],gp:r.gp,goals:r.goals,assists:r.assists,points:r.points})),d=>d.v,fmt,(m==='gp'?'Games played':'Points')+' by season',d=>d.name+': '+d.gp+' GP, '+d.goals+' G, '+d.assists+' A, '+d.points+' PTS');});
dash.draw('g_search',(el)=>{const g=dash.data('player_profiles');const rows=(g.status==='ok'&&g.data)?g.data:[];let i=el.querySelector('input');let dl=el.querySelector('datalist');if(!i){i=document.createElement('input');i.type='search';i.setAttribute('list','g_dl');i.placeholder='Type a name, e.g. Kyle Connor';i.setAttribute('aria-label','Find a player');i.className='dash-select';i.style.minWidth='260px';dl=document.createElement('datalist');dl.id='g_dl';i.onchange=()=>{const v=i.value.trim();if(!v)return;const G=dash.data('player_profiles');const R=(G.status==='ok'&&G.data)?G.data:[];const base={tab:'players',decade:'',position:'',conference:'',school:'',pseason:'',pdraft:'',phonor:'',mingp:'0'};const ex=R.find(r=>r.player+' ('+r.school+')'===v);if(ex){dash.setParams({...base,q:ex.player,pick:ex.player+'|'+ex.school});}else{const lc=v.toLowerCase();const hit=R.filter(r=>r.player.toLowerCase().includes(lc));dash.setParams({...base,q:v,pick:hit.length===1?hit[0].player+'|'+hit[0].school:''});}i.value='';};el.replaceChildren(i,dl);}if(rows.length&&!dl.children.length){dl.replaceChildren(...rows.map(r=>r.player+' ('+r.school+')').sort().map(t=>{const o=document.createElement('option');o.value=t;return o;}));}});
function xesc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g,'');}
function colL(i){let s='';for(i++;i>0;i=Math.floor((i-1)/26))s=String.fromCharCode(65+(i-1)%26)+s;return s;}
const CRCT=(()=>{const t=[];for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0;}return t;})();
function crc32(b){let c=0xFFFFFFFF;for(let i=0;i<b.length;i++)c=CRCT[(c^b[i])&255]^(c>>>8);return (c^0xFFFFFFFF)>>>0;}
function zipStore(files){const enc=new TextEncoder();const parts=[],cd=[];let off=0;for(const [n,d] of files){const nb=enc.encode(n),crc=crc32(d);const lh=new DataView(new ArrayBuffer(30));lh.setUint32(0,0x04034b50,true);lh.setUint16(4,20,true);lh.setUint16(6,0x0800,true);lh.setUint16(12,0x21,true);lh.setUint32(14,crc,true);lh.setUint32(18,d.length,true);lh.setUint32(22,d.length,true);lh.setUint16(26,nb.length,true);parts.push(new Uint8Array(lh.buffer),nb,d);const ch=new DataView(new ArrayBuffer(46));ch.setUint32(0,0x02014b50,true);ch.setUint16(4,20,true);ch.setUint16(6,20,true);ch.setUint16(8,0x0800,true);ch.setUint16(14,0x21,true);ch.setUint32(16,crc,true);ch.setUint32(20,d.length,true);ch.setUint32(24,d.length,true);ch.setUint16(28,nb.length,true);ch.setUint32(42,off,true);cd.push(new Uint8Array(ch.buffer),nb);off+=30+nb.length+d.length;}let cs=0;for(const c of cd)cs+=c.length;const e=new DataView(new ArrayBuffer(22));e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,cs,true);e.setUint32(16,off,true);return new Blob([...parts,...cd,new Uint8Array(e.buffer)],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});}
function sheetXml(rows){let cols=[];for(const r of rows.slice(0,50))for(const k of Object.keys(r)){const v=r[k];if(v!==null&&typeof v==='object')continue;if(!cols.includes(k))cols.push(k);}const n=Math.max(cols.length,1);const last=colL(n-1)+(rows.length+1);let x='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="'+n+'" width="16" customWidth="1"/></cols><sheetData>';x+='<row r="1">'+cols.map((c,j)=>'<c r="'+colL(j)+'1" t="inlineStr" s="1"><is><t xml:space="preserve">'+xesc(c)+'</t></is></c>').join('')+'</row>';rows.forEach((r,i)=>{const rn=i+2;x+='<row r="'+rn+'">'+cols.map((c,j)=>{const v=r[c];if(v===null||v===undefined||v==='')return '';const ref=colL(j)+rn;if(typeof v==='number'&&isFinite(v))return '<c r="'+ref+'"><v>'+v+'</v></c>';if(typeof v==='boolean')return '<c r="'+ref+'" t="b"><v>'+(v?1:0)+'</v></c>';return '<c r="'+ref+'" t="inlineStr"><is><t xml:space="preserve">'+xesc(v)+'</t></is></c>';}).join('')+'</row>';});return x+'</sheetData>'+(rows.length?'<autoFilter ref="A1:'+last+'"/>':'')+'</worksheet>';}
function downloadBook(file,sheets){const enc=new TextEncoder();const H='<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';const R='http://schemas.openxmlformats.org/officeDocument/2006/relationships';const M='http://schemas.openxmlformats.org/spreadsheetml/2006/main';const SH=sheets.filter(s=>s[1]);const names=SH.map(s=>String(s[0]).replace(/[\\\/\?\*\[\]:]/g,' ').slice(0,31));const F=[['[Content_Types].xml',enc.encode(H+'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'+names.map((n,i)=>'<Override PartName="/xl/worksheets/sheet'+(i+1)+'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>').join('')+'</Types>')],['_rels/.rels',enc.encode(H+'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="'+R+'/officeDocument" Target="xl/workbook.xml"/></Relationships>')],['xl/workbook.xml',enc.encode(H+'<workbook xmlns="'+M+'" xmlns:r="'+R+'"><sheets>'+names.map((n,i)=>'<sheet name="'+xesc(n)+'" sheetId="'+(i+1)+'" r:id="rId'+(i+1)+'"/>').join('')+'</sheets></workbook>')],['xl/_rels/workbook.xml.rels',enc.encode(H+'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+names.map((n,i)=>'<Relationship Id="rId'+(i+1)+'" Type="'+R+'/worksheet" Target="worksheets/sheet'+(i+1)+'.xml"/>').join('')+'<Relationship Id="rId'+(names.length+1)+'" Type="'+R+'/styles" Target="styles.xml"/></Relationships>')],['xl/styles.xml',enc.encode(H+'<styleSheet xmlns="'+M+'"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>')]];SH.forEach((s,i)=>F.push(['xl/worksheets/sheet'+(i+1)+'.xml',enc.encode(sheetXml(s[1]))]));const blob=zipStore(F);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=file;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},1500);}
const XTAB={readme:[],alumni:[['Production','agg']],impact:[['Share by decade','impact'],['Decade trend','trend']],seasons:[['Season by season','sbyseason'],['Share by school','srank']],players:[['Players','pall']],dev:[['Development and honors','dev']],now:[['By group','cur'],['Players','curp']],prog:[['Programs','progd']],h2h:[['Head to head','h2h']]};
function getRows(n){const g=dash.data(n);return (g&&g.status==='ok'&&g.data)?g.data:null;}
const xbtn=(id,fn)=>{const b=document.getElementById(id);if(b)b.addEventListener('click',()=>{try{fn();}catch(e){console.error(e);alert('The download could not be created here.');}});};
xbtn('x-view',()=>{const p=dash.params();const t=p.tab||'readme';const sh=[['Filters',[{Tab:t,Scope:scope(p),Note:'Exported '+new Date().toISOString().slice(0,10)+' from the College hockey alumni dashboard. Data: NHL public stats API, pulled November 15, 2026. NCAA Division I only.'}]]];for(const [nm,src] of XTAB[t])sh.push([nm,getRows(src)]);downloadBook('college_hockey_'+t+'_view.xlsx',sh);});
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>dash.setParams({tab:b.getAttribute('data-go')})));
const xAll=()=>{const ids=['players','player_seasons','player_profiles','seasons','league','league_seasons','schools','current','programs'];const sh=[['README',[{About:'College hockey alumni in the NHL, master data (NHL public stats API, pulled November 15, 2026). NCAA Division I alumni only, credited to last college; WHA excluded; regular season; 1960-61 to 2026-27 (2026-27 is partial, to date); current = the 2026-27 roster view. Sheets: players (player by decade), player_seasons, player_profiles (draft, Cups, Hobey, NHL trophies), seasons, league, league_seasons, schools, current, programs.'}]]];for(const n of ids)sh.push([n,getRows(n)]);downloadBook('college_hockey_master_data.xlsx',sh);};
xbtn('x-all',xAll);xbtn('x-all2',xAll);
function ul(el,L){const a=L.filter(Boolean);if(!a.length){el.textContent='Nothing to highlight for these filters.';return;}el.replaceChildren(...a.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));}
const top1=(rows,k,dir,min)=>sorted(min?rows.filter(min):rows,k,dir||'desc')[0];
dash.draw('insA',(el)=>{const g=dash.data('agg');if(g.status!=='ok'||!g.data||!g.data.length){el.textContent='—';return;}const R=g.data,cf=dash.params().by==='conference',by=cf?'conference':'school',L=[];const a=top1(R,'points');L.push(a.name+' leads all '+by+'s with '+fmt(a.points)+' NHL points from '+fmt(a.players)+' players.');const b=top1(R,'players');if(b.name!==a.name)L.push(b.name+' has the most alumni ('+fmt(b.players)+').');const mg=cf?1000:200;const c=top1(R,'ppg','desc',r=>r.gp>=mg);if(c)L.push(c.name+' has the best points per game ('+f2(c.ppg)+', minimum '+fmt(mg)+' games).');if(R.length>5){const t=sorted(R,'points','desc');L.push('The top five '+by+'s account for '+pct(d3.sum(t.slice(0,5),r=>r.points)/d3.sum(R,r=>r.points))+' of all alumni points in view.');}ul(el,L);});
dash.draw('insB',(el)=>{const g=dash.data('impact');if(g.status!=='ok'||!g.data||!g.data.length){el.textContent='—';return;}const R=g.data,by=dash.params().iby==='conference'?'conference':'school',L=[];const a=top1(R,'spoints');L.push(a.name+' has the largest share of NHL points ('+pct(a.spoints)+') among '+by+'s in view.');const b=top1(R,'sgoals');if(b.name!==a.name)L.push(b.name+' leads in share of NHL goals ('+pct(b.sgoals)+').');const c=top1(R,'sgp');if(c.name!==a.name)L.push(c.name+' leads in share of NHL games played ('+pct(c.sgp)+').');if(R.length>5){const t=sorted(R,'spoints','desc');L.push('The top five '+by+'s together hold '+pct(d3.sum(t.slice(0,5),r=>r.spoints))+' of NHL points.');}ul(el,L);});
dash.draw('insC',(el)=>{const g=dash.data('sbyseason');if(g.status!=='ok'||!g.data||!g.data.length){el.textContent='—';return;}const R=g.data,L=[];const hi=top1(R,'spoints'),lo=top1(R,'spoints','asc');L.push('Peak season for the alumni share of NHL points: '+hi.season+' ('+pct(hi.spoints)+').');if(lo.season!==hi.season)L.push('Lowest: '+lo.season+' ('+pct(lo.spoints)+').');if(R.length>1){const f=R[0],l=R[R.length-1];L.push('From '+f.season+' to '+l.season+', the share of NHL points moved from '+pct(f.spoints)+' to '+pct(l.spoints)+'.');}const pl=top1(R,'players');L.push(pl.season+' had the most alumni player-seasons ('+fmt(pl.players)+').');ul(el,L);});
dash.draw('insD',(el)=>{const g=dash.data('pall');if(g.status!=='ok'||!g.data||!g.data.length){el.textContent='—';return;}const R=g.data,L=[];const a=top1(R,'points');L.push(a.player+' ('+a.school+') has the most points in view, '+fmt(a.points)+' in '+fmt(a.gp)+' games.');const b=top1(R,'gp');if(b.player!==a.player)L.push(b.player+' ('+b.school+') has the most games played ('+fmt(b.gp)+').');const c=top1(R,'ppg','desc',r=>r.gp>=200);if(c)L.push(c.player+' has the best points per game with at least 200 games ('+f2(c.ppg)+').');L.push(pct(R.filter(r=>r.overall<999).length/R.length)+' of these players were drafted, and '+fmt(R.filter(r=>r.cups>0).length)+' won a Stanley Cup.');ul(el,L);});
dash.draw('insE',(el)=>{const g=dash.data('dev');if(g.status!=='ok'||!g.data||!g.data.length){el.textContent='—';return;}const R=g.data,by=dash.params().dby==='conference'?'conference':'school',L=[];const big=r=>r.players>=10;const a=top1(R,'pdrafted','desc',big);if(a)L.push(a.name+' has the highest share of drafted players ('+pct(a.pdrafted)+', minimum 10 players).');const b=top1(R,'r1');if(b&&b.r1>0)L.push(b.name+' has produced the most first-round picks ('+fmt(b.r1)+').');const c=top1(R,'avgAge','asc',r=>big(r)&&r.avgAge>0);if(c)L.push(c.name+' players reach the NHL youngest, at '+f1(c.avgAge)+' on average.');const d=top1(R,'cupPl');if(d&&d.cupPl>0)L.push(d.name+' has the most Stanley Cup winners ('+fmt(d.cupPl)+').');const e=top1(R,'g500');if(e&&e.g500>0)L.push(e.name+' has the most 500+ game players ('+fmt(e.g500)+').');ul(el,L);});
dash.draw('insF',(el)=>{const g=dash.data('cur');if(g.status!=='ok'||!g.data||!g.data.length){el.textContent='—';return;}const R=g.data,by=dash.params().nby||'school',L=[];const nm=by==='team'?'NHL team':by;const a=top1(R,'players');L.push(a.name+' is the '+nm+' with the most alumni on 2026-27 rosters ('+fmt(a.players)+').');const b=top1(R,'points');if(b.name!==a.name)L.push(b.name+' leads in points so far ('+fmt(b.points)+').');const c=top1(R,'rookies');if(c&&c.rookies>0)L.push(c.name+' has the most alumni in their first NHL season ('+fmt(c.rookies)+').');ul(el,L);});
dash.draw('insG',(el)=>{const g=dash.data('progd');if(g.status!=='ok'||!g.data||!g.data.length){el.textContent='—';return;}const R=g.data,L=[];const a=top1(R,'perDec');L.push(a.name+' has the most alumni per 10 program-years ('+f2(a.perDec)+' over '+fmt(a.years)+' program-years).');const b=top1(R,'ptsPY');if(b.name!==a.name)L.push(b.name+' leads in NHL points per program-year ('+f1(b.ptsPY)+').');const c=top1(R,'players');if(c.name!==a.name)L.push(c.name+' has the most alumni overall ('+fmt(c.players)+') but ranks lower per program-year.');ul(el,L);});
